contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v1, uint v2) public {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        require(reverted);
        assert(c.MinSum() == beforeMinSum);
    }
}

